# (stem, correct, [d0,d1,d2], pos, why)
M11=[
(r"Let $f(x)=x^3-4x^2-5x$. Which list gives all of the zeros of $f$?",
 r"$-1,\ 0,\ 5$",[r"$-5,\ 0,\ 1$",r"$-1,\ 5$",r"$0,\ 4,\ 5$"],0,
 r"$f(x)=x(x-5)(x+1)$. {d0}: sign error, reading each factor $x-a$ as $x=-a$. {d1}: divided out the common factor $x$ and lost the zero at $0$. {d2}: read the coefficients $4$ and $5$ as zeros."),
(r"Let $r(x)=\dfrac{x^2-x-6}{x^2-9}$. What are the coordinates of the hole in the graph of $r$?",
 r"$\left(3,\dfrac56\right)$",[r"$(3,0)$",r"$(3,1)$",r"$\left(3,\dfrac65\right)$"],2,
 r"$r(x)=\dfrac{(x-3)(x+2)}{(x-3)(x+3)}$, so the hole is where $x=3$ and the reduced value is $\dfrac{3+2}{3+3}=\dfrac56$. {d0}: used the original numerator, which is $0$ at $x=3$. {d1}: used the horizontal asymptote as the $y$-value. {d2}: inverted the reduced fraction."),
(r"What is the quotient when $3x^3-2x^2+x-4$ is divided by $x-1$?",
 r"$3x^2+x+2$",[r"$3x^2-2x+1$",r"$3x^2-5x+6$",r"$3x^2+x$"],1,
 r"Synthetic division with $1$: $3,-2,1,-4\to3,1,2,-2$; quotient $3x^2+x+2$, remainder $-2$. {d0}: copied the coefficients without adding the carried values. {d1}: divided by $x+1$ (used $-1$). {d2}: added the remainder $-2$ into the quotient."),
(r"Which line is the slant asymptote of $r(x)=\dfrac{x^2+5x+3}{x+2}$?",
 r"$y=x+3$",[r"$y=x+5$",r"$y=x-3$",r"$y=x+2$"],3,
 r"Synthetic division with $-2$: $1,5,3\to1,3,-3$; $r(x)=x+3-\dfrac{3}{x+2}$. {d0}: used the numerator's middle coefficient. {d1}: used the remainder as the constant. {d2}: used the divisor's constant."),
(r"What is the coefficient of $x^2$ in the expansion of $(x-2)^4$?",
 r"$24$",[r"$-24$",r"$6$",r"$12$"],3,
 r"Row $4$ is $1,4,6,4,1$, so the term is $6\cdot x^2\cdot(-2)^2=24x^2$. {d0}: made the sign negative (even power of $-2$ is positive). {d1}: used the Pascal number only. {d2}: used $6\cdot2$, forgetting to square $-2$."),
(r"Which statement about the graph of $r(x)=\dfrac{x^2-4}{x^2-x-2}$ is true?",
 r"A hole at $x=2$ and a vertical asymptote at $x=-1$",[r"Vertical asymptotes at $x=2$ and $x=-1$",r"A hole at $x=-1$ and a vertical asymptote at $x=2$",r"A hole at $x=-2$ and a vertical asymptote at $x=1$"],1,
 r"$r(x)=\dfrac{(x-2)(x+2)}{(x-2)(x+1)}$: the factor $x-2$ cancels (hole), $x+1$ remains (asymptote). {d0}: treated every zero of the denominator as an asymptote. {d1}: swapped the roles of the two factors. {d2}: sign error, reading $x-a$ as $x=-a$."),
(r"Which statement describes the end behavior of $f(x)=-2(x+1)^2(x-3)$?",
 r"$f(x)\to-\infty$ as $x\to\infty$ and $f(x)\to\infty$ as $x\to-\infty$",[r"$f(x)\to\infty$ as $x\to\infty$ and $f(x)\to-\infty$ as $x\to-\infty$",r"$f(x)\to-\infty$ as $x\to\infty$ and as $x\to-\infty$",r"$f(x)\to\infty$ as $x\to\infty$ and as $x\to-\infty$"],2,
 r"Leading term $-2x^2\cdot x=-2x^3$: odd degree, negative coefficient. {d0}: ignored the negative leading coefficient. {d1}: treated the squared factor as making the whole degree even. {d2}: both errors together."),
(r"Which is the expansion of $(2x-1)^3$?",
 r"$8x^3-12x^2+6x-1$",[r"$2x^3-3x^2+3x-1$",r"$8x^3+12x^2+6x+1$",r"$8x^3-1$"],0,
 r"Row $3$ is $1,3,3,1$ with $a=2x$, $b=-1$. {d0}: did not cube the $2$ in $2x$. {d1}: dropped the negative signs. {d2}: used $(a-b)^3=a^3-b^3$, losing the middle terms."),
]
