M12=[
(r"The point $(1,5)$ lies on the graph of $f$. What is the image of this point on the graph of $g(x)=f(x-3)+2$?",
 r"$(4,7)$",[r"$(-2,7)$",r"$(4,3)$",r"$(-2,3)$"],0,
 r"$x-3$ shifts right $3$: $x=4$; $+2$ shifts up $2$: $y=7$. {d0}: horizontal sign error (moved left). {d1}: vertical sign error (moved down). {d2}: both sign errors."),
(r"What is the vertex of the graph of $g(x)=-2(x+4)^2+1$, a transformation of $f(x)=x^2$?",
 r"$(-4,1)$",[r"$(4,1)$",r"$(-4,-1)$",r"$(-8,1)$"],2,
 r"$x+4$ moves the vertex left $4$; $+1$ moves it up $1$. The dilation and reflection do not move the vertex. {d0}: horizontal sign error. {d1}: applied the reflection to the vertical translation. {d2}: multiplied the shift by the dilation factor."),
(r"The point $(6,-3)$ lies on the graph of $f$. What is the image of this point on the graph of $g(x)=f(2x)$?",
 r"$(3,-3)$",[r"$(12,-3)$",r"$(6,-6)$",r"$(3,3)$"],1,
 r"Horizontal dilation by $\dfrac{1}{|2|}$: $x=\dfrac62=3$, $y$ unchanged. {d0}: multiplied $x$ by $b$ instead of dividing. {d1}: treated $f(2x)$ as a vertical dilation. {d2}: also reflected over the $x$-axis."),
(r"Let $f(x)=\sqrt{x}$ and $g(x)=f(-x)$. What are the domain and range of $g$?",
 r"Domain $(-\infty,0]$, range $[0,\infty)$",[r"Domain $[0,\infty)$, range $[0,\infty)$",r"Domain $(-\infty,0]$, range $(-\infty,0]$",r"Domain $[0,\infty)$, range $(-\infty,0]$"],3,
 r"$f(-x)$ reflects over the $y$-axis: $-x\ge0$ gives domain $(-\infty,0]$; outputs stay $\ge0$. {d0}: assumed the domain does not change. {d1}: also reflected the range. {d2}: used an $x$-axis reflection instead."),
(r"The graph of $g$ is the graph of $f$ shifted left $2$ units, dilated vertically by a factor of $3$, and reflected over the $x$-axis. Which equation defines $g$?",
 r"$g(x)=-3f(x+2)$",[r"$g(x)=-3f(x-2)$",r"$g(x)=-3f(x)+2$",r"$g(x)=-\dfrac13f(x+2)$"],1,
 r"Left $2$ is $f(x+2)$; dilation by $3$ with reflection is $-3f$. {d0}: horizontal sign error. {d1}: put the shift outside, making it vertical. {d2}: used the reciprocal as the dilation factor."),
(r"The function $f$ has domain $[-4,8]$. What is the domain of $g(x)=f\!\left(\dfrac{x}{2}\right)$?",
 r"$[-8,16]$",[r"$[-2,4]$",r"$[-4,8]$",r"$[-8,8]$"],2,
 r"Need $-4\le\dfrac{x}{2}\le8$, so $-8\le x\le16$. {d0}: divided the endpoints by $2$. {d1}: assumed the domain is unchanged. {d2}: doubled only the left endpoint."),
(r"The function $f$ has range $[1,5]$. What is the range of $g(x)=-2f(x)+3$?",
 r"$[-7,1]$",[r"$[-10,-2]$",r"$[-16,-8]$",r"$[5,13]$"],3,
 r"$-2(1)+3=1$ and $-2(5)+3=-7$, so the range is $[-7,1]$. {d0}: forgot the $+3$. {d1}: added $3$ before multiplying, computing $-2(f+3)$. {d2}: ignored the negative sign of $-2$."),
(r"The point $(4,2)$ lies on the graph of $f$. What is the image of this point on the graph of $g(x)=-f\!\left(\dfrac{x}{4}\right)+1$?",
 r"$(16,-1)$",[r"$(1,-1)$",r"$(16,3)$",r"$(16,-3)$"],0,
 r"$x$: multiply by $\dfrac{1}{|1/4|}=4$ to get $16$. $y$: $-2+1=-1$. {d0}: divided $x$ by $4$. {d1}: missed the reflection. {d2}: added $1$ before reflecting, computing $-(2+1)$."),
]
