M13=[
(r"A table gives $y=5,9,13,17,21$ for $x=0,1,2,3,4$. Which model fits the data?",
 r"Linear, $y=4x+5$",[r"Quadratic, $y=4x^2+5$",r"Linear, $y=5x+4$",r"Linear, $y=9x+5$"],0,
 r"Every first difference is $4$, so the rate is constant: slope $4$, intercept $5$. {d0}: assumed increasing data is quadratic. {d1}: swapped slope and intercept. {d2}: used $y(1)$ as the slope."),
(r"A table gives $y=3,4,9,18,31$ for $x=0,1,2,3,4$. Which function fits the data?",
 r"$y=2x^2-x+3$",[r"$y=4x^2-x+3$",r"$y=2x^2+x+3$",r"$y=2x^2-x+4$"],2,
 r"First differences $1,5,9,13$; second differences $4,4,4$, so $2a=4$ and $a=2$; then $c=3$ and $b=-1$. {d0}: used the second difference as $a$. {d1}: sign error in $b$. {d2}: took $c$ from $y(1)$."),
(r"A table gives $y=2,3,10,29,66,127$ for $x=0,1,2,3,4,5$. The $n$th differences are constant. What is $n$?",
 r"$3$",[r"$2$",r"$5$",r"$6$"],1,
 r"Differences: $1,7,19,37,61$; then $6,12,18,24$; then $6,6,6$. The third differences are constant. {d0}: stopped at the second differences. {d1}: used the number of points minus one. {d2}: gave the value of the constant difference."),
(r"A rectangle has perimeter $60$ m and width $w$. Which function type best models its area $A(w)$?",
 r"Quadratic",[r"Linear",r"Cubic",r"Piecewise-defined"],3,
 r"Length is $30-w$, so $A(w)=w(30-w)$, a two-dimensional (area) context. {d0}: assumed linear because the perimeter is linear in $w$. {d1}: confused area with volume. {d2}: no change of rule over intervals occurs."),
(r"A rectangle has perimeter $60$ m and width $w$, so its area is $A(w)=w(30-w)$. Which domain restriction fits the context?",
 r"$0<w<30$",[r"All real numbers",r"$w>0$",r"$0<w<60$"],2,
 r"Width and length $30-w$ must both be positive. {d0}: no restriction considered. {d1}: only checked the width. {d2}: used the perimeter, $60$, as the upper limit."),
(r"Eight points on a graph have distinct input values. A polynomial function of degree at most $n$ passes through all eight points. What is the least value of $n$ that is guaranteed?",
 r"$7$",[r"$8$",r"$6$",r"$4$"],1,
 r"$n+1$ points with distinct inputs lie on a polynomial of degree at most $n$, so $n=7$. {d0}: set $n$ equal to the number of points. {d1}: subtracted one too many. {d2}: halved the number of points."),
(r"Which situation is best modeled by a piecewise-defined function?",
 r"A taxi fare of $3$ dollars for the first $2$ km, then $1.50$ dollars for each additional km",[r"The distance driven at a constant $60$ km/h",r"The area of a square of side $s$",r"The volume of a cube of edge $s$"],0,
 r"The rate of change differs on two intervals. {d0}: constant rate gives a linear model. {d1}: area gives a quadratic. {d2}: volume gives a cubic."),
(r"A model for tickets sold is $T(p)=200-8p$, where $p$ is the ticket price in dollars. Which assumption is built into the model?",
 r"Each $1$ dollar increase in price lowers sales by $8$ tickets",[r"Sales stay at $200$ tickets whatever the price",r"Sales increase as the price increases",r"Prices must be whole numbers of dollars"],3,
 r"The model is linear: the rate of change is constant at $-8$ tickets per dollar. {d0}: read the intercept as a constant. {d1}: sign error on the slope. {d2}: confused a domain restriction with an assumption about change."),
]
